某游戏的排行榜系统需要实时更新玩家分数。每次只有一个玩家的分数发生变化，排榜已经是按分数降序排列的。现在需要将更新后的玩家调整到正确位置。下面的函数updateRanking()要实现上述功能，则两处横线上应分别填写（）。
struct Player {
    string name;
    int score;
};
void updateRanking(Player players[], int size, int playerIdx) {
    Player updatedPlayer = players[playerIdx];
    if (playerIdx > 0 && updatedPlayer.score > players[playerIdx - 1].score) {
        int i = playerIdx;
        while (______) { // 第一处
            players[i] = players[i - 1];
            i--;
        }
        players[i] = updatedPlayer;
    } else if (playerIdx < size - 1 && updatedPlayer.score < players[playerIdx + 1].score) {
        int i = playerIdx;
        while (______) { // 第二处
            players[i] = players[i + 1];
            i++;
        }
        players[i] = updatedPlayer;
    }
}

给定如下算法，其时间复杂度为（）。
bool f(int arr[], int n, int target) {
    for (int i = 0; i < n; i++) {
        int sum = 0;
        for (int j = 0; j < n; j++) {
            if (i & (1 << j)) {
                sum += arr[j];
            }
        }
        if (sum == target) return true;
    }
    return false;
}

